import{c as s,Q as i,j as o,m as n}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"ADR-064 — Pipeline runner: single tsx-entrypoint image, docker compose run --rm on-demand invocation, no long-running scheduler service","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-064.md","filePath":"adr/ADR-064.md"}'),t={name:"adr/ADR-064.md"};function a(r,e,c,l,d,p){return i(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="adr-064-—-pipeline-runner-single-tsx-entrypoint-image-docker-compose-run-rm-on-demand-invocation-no-long-running-scheduler-service" tabindex="-1">ADR-064 — Pipeline runner: single <code>tsx</code>-entrypoint image, <code>docker compose run --rm</code> on-demand invocation, no long-running scheduler service <a class="header-anchor" href="#adr-064-—-pipeline-runner-single-tsx-entrypoint-image-docker-compose-run-rm-on-demand-invocation-no-long-running-scheduler-service" aria-label="Permalink to &quot;ADR-064 — Pipeline runner: single \`tsx\`-entrypoint image, \`docker compose run --rm\` on-demand invocation, no long-running scheduler service&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-22 Closes into · RFC-024 §4, §5, §6 Related ADRs · ADR-014 (GH Pages deploy), ADR-063 (web container) Closes follow-ups · The &quot;all pipelines I want to be able to run as docker process on demand&quot; requirement from the RFC-024 scoping pass</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Orrery has ~10 data pipelines exposed as <code>npm run …</code> scripts: <code>fetch-launches</code>, <code>images:hotspots</code>, <code>fetch-assets</code>, <code>build-image-provenance</code>, <code>build-link-provenance</code>, <code>validate-data</code>, <code>build-science-index</code>, <code>build-tech-bom</code>, <code>precompute-porkchops</code>, <code>check-learn-links</code>. Today each runs either on a contributor&#39;s host (with whatever system gdal/sharp version that machine has) or on a GH Actions runner (<code>refresh-launches.yml</code>, <code>ci.yml</code>, <code>release.yml</code>).</p><p>RFC-024 wants every one of these runnable as a docker process so (a) contributors don&#39;t need a working <code>gdal-async</code> build chain on their laptop; (b) the eventual VPS can host pipeline runs that don&#39;t fit GH Actions cron windows; (c) the local + CI artefacts that pipelines produce are bit-identical to what production will produce.</p><p>The decision is the <em>invocation pattern</em>: how does the operator (or CI step) reach a script inside a container, what&#39;s the entry contract, and is there a long-running service in the mix or only on-demand containers? Three shapes were on the table — long-running pipeline daemon, on-demand <code>docker compose run</code>, or sidecar-with-internal-cron. RFC-024 §6 settled on on-demand.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>One image — the <code>pipeline</code> stage of the multi-stage Dockerfile in ADR-063 — carrying Node 20 + <code>tsx</code> + system gdal + the locked <code>node_modules</code>. ENTRYPOINT is <code>[&quot;npx&quot;,&quot;tsx&quot;]</code>. The compose service <code>pipeline-runner</code> is declared with <code>profiles: [&#39;manual&#39;]</code> so <code>docker compose up</code> does NOT start it. Operators invoke pipelines via <code>docker compose run --rm pipeline-runner &lt;script.ts&gt; [args]</code>, which spawns a one-shot container that exits when the script does. <code>package.json</code> provides short <code>docker:&lt;pipeline-name&gt;</code> wrappers so the CLI surface matches the existing <code>npm run …</code> form.</strong></p><h3 id="image-content" tabindex="-1">Image content <a class="header-anchor" href="#image-content" aria-label="Permalink to &quot;Image content&quot;">​</a></h3><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:20-bookworm-slim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apt-get update &amp;&amp; apt-get install -y --no-install-recommends \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      libgdal-dev gdal-bin \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ca-certificates curl \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &amp;&amp; rm -rf /var/lib/apt/lists/*</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /repo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package.json package-lock.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm ci          # installs gdal-async against system gdal</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tsx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Image carries:</p><ul><li>Node 20 + <code>npm</code> (matches <code>.github/workflows/ci.yml</code>).</li><li>System gdal (<code>libgdal-dev</code> + <code>gdal-bin</code>) so <code>gdal-async</code> resolves at runtime.</li><li>The full <code>node_modules</code> from <code>package-lock.json</code>. No source code.</li></ul><p>Image does <strong>not</strong> carry repo source — that&#39;s bind-mounted from the host at runtime (<code>volumes: [.:/repo:ro]</code>). This is the deliberate trade-off for local dev: a script edit doesn&#39;t require a container rebuild.</p><h3 id="compose-entry" tabindex="-1">Compose entry <a class="header-anchor" href="#compose-entry" aria-label="Permalink to &quot;Compose entry&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pipeline-runner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pipeline</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;manual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">orrery-data:/repo/static/data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # rw — pipelines write here</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">orrery-cache:/repo/.image-cache</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # rw — caches for HiRISE JP2s, GCAT TSV, LL2 responses</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.:/repo:ro</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # ro — source code for tsx</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LL2_PATREON_KEY=\${LL2_PATREON_KEY:-}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NODE_OPTIONS=--max-old-space-size=4096</span></span></code></pre></div><p><code>profiles: [&#39;manual&#39;]</code> is the linchpin. With it, <code>docker compose up</code> only brings up services without a profile (i.e. <code>web</code>). The pipeline-runner only exists when the operator types <code>docker compose run --rm pipeline-runner …</code>.</p><p><code>--rm</code> is the second linchpin. It deletes the one-shot container on exit. Without it, <code>docker ps -a</code> accumulates stopped containers from every pipeline invocation.</p><h3 id="invocation-surface" tabindex="-1">Invocation surface <a class="header-anchor" href="#invocation-surface" aria-label="Permalink to &quot;Invocation surface&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Long form — what the wrapper scripts shell out to</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline-runner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/fetch-launches.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Short form — what humans use</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:fetch-launches</span></span></code></pre></div><p>The <code>npm</code> wrapper layer is in <code>package.json</code>. Every pipeline gets a <code>docker:&lt;name&gt;</code> script that calls the long form. The wrapper layer is the API; the long form is the mechanism.</p><h3 id="arguments-and-env" tabindex="-1">Arguments and env <a class="header-anchor" href="#arguments-and-env" aria-label="Permalink to &quot;Arguments and env&quot;">​</a></h3><p>Pipeline args pass through transparently: <code>docker compose run --rm pipeline-runner scripts/fetch-launches.ts --since 2026-05-01</code> works because the <code>tsx</code> entrypoint takes the script path + args verbatim.</p><p>Pipelines that need secrets read them from a repo-root <code>.env</code> (gitignored). Compose loads this automatically into <code>pipeline-runner</code>&#39;s environment. CI sets them directly via <code>\${‌{ secrets.* }}</code> (GH Actions secret-context syntax). Same shape as the existing <code>refresh-launches.yml</code>.</p><h3 id="what-we-are-not-doing" tabindex="-1">What we are NOT doing <a class="header-anchor" href="#what-we-are-not-doing" aria-label="Permalink to &quot;What we are NOT doing&quot;">​</a></h3><ul><li><strong>No long-running pipeline service.</strong> Some Compose-based projects run a &quot;worker&quot; daemon that loops, polls a queue, and processes jobs. Out of scope. Pipelines here are batch — they ingest, transform, write, exit. A daemon adds restart-policy reasoning, healthcheck reasoning, and a lifecycle we don&#39;t need.</li><li><strong>No internal cron container.</strong> Could schedule refreshes inside the stack via an alpine + crond sidecar. Out of scope for this RFC. The host crontab (or systemd.timer once we get to a VPS) is the obvious place; <code>refresh-launches.yml</code> is the obvious place today. Adding a third scheduler would compete with both.</li><li><strong>No <code>tsx watch</code> or hot-reload entrypoint.</strong> Pipelines run once, write the artefact, exit. Re-invoking is cheap (~2-5s overhead).</li><li><strong>No exposed network port on pipeline-runner.</strong> Nothing connects to it. It&#39;s not a service.</li><li><strong>No HTTP/RPC pipeline trigger API.</strong> The &quot;trigger&quot; is <code>docker compose run</code>. If we want webhooks (e.g. &quot;GitHub push → run images:hotspots refresh&quot;) later, that&#39;s a separate component, not a property of the pipeline image.</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><p>On-demand <code>docker compose run --rm</code> is the simplest invocation shape that:</p><ul><li>Maps 1:1 with the existing <code>npm run &lt;script&gt;</code> surface (operators don&#39;t have to relearn).</li><li>Avoids a lifecycle for the pipeline tier (no restart policies, no healthchecks, no &quot;pipeline service crashed at 3am&quot; pages).</li><li>Composes cleanly with CI (the same one-liner works in a workflow step).</li><li>Naturally serialises — two <code>docker compose run --rm pipeline-runner …</code> invocations are independent processes; they share the data volume but don&#39;t deadlock or stomp on each other unless the <em>scripts themselves</em> race (which is an existing property of the scripts, not introduced by docker).</li></ul><p><code>profiles: [&#39;manual&#39;]</code> is the docker-native way to declare &quot;this service exists but isn&#39;t started by <code>up</code>.&quot; Without it, <code>docker compose up</code> would start the pipeline-runner with no entrypoint args (or with <code>[&quot;npx&quot;,&quot;tsx&quot;]</code> and nothing to run), and it&#39;d exit immediately with code 0, generating noise. With profiles, the service is <em>latent</em> until explicitly invoked.</p><p>Source bind-mount (<code>.:/repo:ro</code>) is the right trade-off for local + CI:</p><ul><li>A script edit doesn&#39;t require <code>docker compose build</code>. The next <code>npm run docker:fetch-launches</code> picks up the change instantly.</li><li>CI checkout populates the bind-mount with the current ref&#39;s source, so the same image runs <code>main</code>-ref scripts on <code>main</code> PRs and feature-branch scripts on feature PRs without rebuilds.</li><li>The trade-off: in the future VPS deploy the bind-mount goes away (no host repo on a VPS), and the pipeline image bakes source in. That&#39;s a known follow-up in RFC-024 §10; doesn&#39;t change the contract here.</li></ul><p><code>node:20-bookworm-slim</code> matches ADR-063&#39;s builder stage (same Node version → same <code>node_modules</code> resolution → no Node-version-skew bugs). System gdal install is a one-time apt-get; subsequent rebuilds hit cache as long as <code>package-lock.json</code> doesn&#39;t move.</p><p>ENTRYPOINT = <code>[&quot;npx&quot;,&quot;tsx&quot;]</code> rather than <code>[&quot;bash&quot;]</code> or <code>[&quot;node&quot;]</code> because:</p><ul><li><code>tsx</code> is what every pipeline script uses already (<code>tsx scripts/fetch-launches.ts</code>).</li><li>Operators don&#39;t have to remember <code>npx tsx scripts/…</code> — they say <code>docker compose run --rm pipeline-runner scripts/…</code> and the entrypoint adds the rest.</li><li>Forbids accidental misuse (shell-escapes inside the container).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Long-running pipeline daemon with a queue.</strong> Adds Redis (or sqlite, or filesystem queue). Lifecycle, restart policy, healthcheck. Solves a problem we don&#39;t have. Rejected.</li><li><strong>Cron container inside the stack</strong> (alpine + crond + script invocations). Compete with <code>refresh-launches.yml</code>. Adds a piece of infrastructure whose only job is invoking the pipeline image — and <code>docker compose run</code> from a host cron is the same thing minus a container. Rejected for the local-dev RFC; revisit in the VPS RFC.</li><li><strong>Separate images for separate pipelines</strong> (one for launches, one for hotspots, one for vision). Each could be smaller (no gdal in the launches image, etc.). Adds 5-10 Dockerfiles and a build-matrix. The shared <code>node_modules</code> is the bulk of every image; specialising base layers wouldn&#39;t recover the size cost. Rejected as premature splitting.</li><li><strong>Run pipelines on the host (no container) but use the data volume on disk.</strong> Defeats the point — contributors still need a working gdal/sharp build chain. Reproducibility argument disappears.</li><li><strong>ENTRYPOINT = <code>[&quot;bash&quot;]</code></strong> with operators typing <code>docker compose run --rm pipeline-runner bash -lc &#39;npx tsx scripts/…&#39;</code>. Longer, easier to typo, no real benefit. Rejected.</li><li><strong>GH Actions remote-trigger / <code>gh workflow run</code> as the &quot;on demand&quot; mechanism</strong> instead of docker. Couples local dev to GH Actions runner availability + minutes. Doesn&#39;t solve the contributor-without-gdal problem. Rejected.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Any contributor can run any pipeline against the live data volume with one <code>npm run docker:…</code> command. No host gdal install. No &quot;works on my mac but not your mac.&quot;</li><li>CI workflows can re-use the same invocation pattern verbatim (<code>docker compose run --rm pipeline-runner scripts/…</code>), so a workflow&#39;s pipeline step matches what an operator runs locally.</li><li>One-shot containers + <code>--rm</code> means there&#39;s no accumulating cruft in <code>docker ps -a</code> and no orphaned named containers blocking re-runs.</li><li>The path to VPS is &quot;swap the bind-mount for a baked-in source COPY&quot; — a one-line Dockerfile change in the future <code>compose.prod.yml</code> overlay, no architectural reshape.</li></ul><p><strong>Negative:</strong></p><ul><li>Per-pipeline cold-start cost: spinning up a container adds ~1-2s on top of the script. Acceptable for batch jobs that run in seconds-to-minutes; would be annoying if these were &lt; 1s pings, which they aren&#39;t.</li><li>The single image carries gdal + sharp + all <code>node_modules</code> even for pipelines that don&#39;t need them (e.g. <code>build-science-index.ts</code> is pure Markdown wrangling). Image is ~1 GB. Acceptable trade-off vs the alternative of multi-image complexity; the host has the bytes.</li><li>Bind-mounting host source means pipeline determinism depends on the host&#39;s working tree. CI is fine (<code>actions/checkout</code>); local invocations against a dirty tree run dirty-tree scripts. This is correct behaviour for dev, not a defect.</li><li>Operators who type <code>docker compose up</code> will see only <code>web</code> start — they have to know <code>pipeline-runner</code> is <code>profiles: [&#39;manual&#39;]</code> and uses <code>run --rm</code>. Documented in <code>docs/guides/docker-stack.md</code> and in <code>--help</code> output of the <code>npm run docker:*</code> wrappers.</li></ul><h2 id="decision-status" tabindex="-1">Decision status <a class="header-anchor" href="#decision-status" aria-label="Permalink to &quot;Decision status&quot;">​</a></h2><p><strong>Accepted on 2026-05-22.</strong> Shipped in commit <code>4789855ee</code> (Slice 1 of RFC-024). The Dockerfile is now repo-root single-stage (no longer a multi-stage with <code>web</code> as the secondary target — see ADR-063&#39;s Amendment for why) and contains only the pipeline-runner image. Verified: <code>docker compose config pipeline-runner</code> parses cleanly, <code>docker build --check</code> returns no warnings, and the <code>profiles: [&#39;manual&#39;]</code> gate means <code>docker compose up -d web</code> neither builds nor starts it. The image only builds on first <code>docker compose run --rm pipeline-runner …</code> — operators don&#39;t pay the ~5-10 min one-time gdal/sharp/canvas compile cost just to serve the static bundle locally.</p>`,43)])])}const k=s(t,[["render",a]]);export{u as __pageData,k as default};
